-- 2026-11-26, after Hot Go Park ("1 2 yes sure"):
-- 1. Hot Go Dreamworld (Wanghua, Fushun): a park under construction since
--    about 2015 and stalled, with a B&M wing coaster (five inversions) and a
--    B&M hyper standing unfinished (Coasterpedia; RCDB screenshot). Both go
--    in as opening soon, unnamed so "Unknown" and "Unknown (2)". The pin is
--    estimated at Wanghua district (no source gives coordinates); listed in
--    missing-parks.md.
-- 2. Hot Go Park's Jungle Walk and Mine Train take the Vekoma models a 2013
--    forum post expected (a suspended family coaster and a mine train).
-- 3. coaster_notes: where a fact rests on an assumption, the note and its
--    link, kept so it can be checked later. Internal for now (public = 0:
--    only admins see them, on the coaster page and on /admin). worker.js
--    answers [] before this table exists.
INSERT INTO parks (name, lat, lon, region, travel) SELECT 'Hot Go Dreamworld', 41.853, 123.80, 'China', 0 WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Hot Go Dreamworld');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT MAX(id) FROM coasters) + ROW_NUMBER() OVER (), v.* FROM (VALUES ('Unknown','Hot Go Dreamworld','Steel','Bolliger & Mabillard','B&M Wing',NULL,NULL,NULL,5,NULL,NULL,NULL,'soon',NULL,NULL,1), ('Unknown (2)','Hot Go Dreamworld','Steel','Bolliger & Mabillard','B&M Hyper',NULL,NULL,NULL,0,NULL,NULL,NULL,'soon',NULL,NULL,1)) v WHERE NOT EXISTS (SELECT 1 FROM coasters c WHERE c.name = v.column1 AND c.park = v.column2);
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.park = 'Hot Go Dreamworld' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id) ORDER BY c.id;
UPDATE coasters SET manu = 'Vekoma', model = CASE name WHEN 'Jungle Walk' THEN 'Vekoma Suspended Family Coaster' ELSE 'Mine Train' END WHERE park = 'Hot Go Park - Happy Jungle World' AND name IN ('Jungle Walk', 'Mine Train') AND manu IS NULL;
CREATE TABLE IF NOT EXISTS coaster_notes (id INTEGER PRIMARY KEY AUTOINCREMENT, coaster_id INTEGER NOT NULL, note TEXT NOT NULL, url TEXT, kind TEXT, public INTEGER NOT NULL DEFAULT 0, added TEXT);
INSERT INTO coaster_notes (coaster_id, note, url, kind, added) WITH v(name, park, note, url, kind) AS (VALUES ('Jungle Walk', 'Hot Go Park - Happy Jungle World', 'Maker and model from a 2013 forum post expecting Vekoma rides here (a suspended family coaster and a mine train). Never confirmed.', 'https://themeparkreview.com/forum/topic/40037-hotgo-park-in-fushun-china', 'model'), ('Mine Train', 'Hot Go Park - Happy Jungle World', 'Maker and model from a 2013 forum post expecting Vekoma rides here (a suspended family coaster and a mine train). Never confirmed.', 'https://themeparkreview.com/forum/topic/40037-hotgo-park-in-fushun-china', 'model'), ('Forest Slide', 'Hot Go Park - Happy Jungle World', 'Standing but not running (RCDB); recorded as closed, date unknown.', NULL, 'status'), ('Mine Train', 'Hot Go Park - Happy Jungle World', 'Standing but not running (RCDB); recorded as closed, date unknown.', NULL, 'status'), ('Unknown', 'Hot Go Dreamworld', 'Unfinished: construction stalled around 2015 (financial and legal trouble). Recorded as opening soon. Park pin estimated.', 'https://coasterpedia.net/wiki/Unknown_B%26M_Wing_Coaster_(Hot_Go_Dreamworld)', 'status'), ('Unknown (2)', 'Hot Go Dreamworld', 'Unfinished: construction stalled around 2015 (financial and legal trouble). Recorded as opening soon. Park pin estimated.', 'https://coasterpedia.net/wiki/Hot_Go_Dreamworld', 'status')) SELECT c.id, v.note, v.url, v.kind, date('now') FROM v JOIN coasters c ON c.name = v.name AND c.park = v.park WHERE NOT EXISTS (SELECT 1 FROM coaster_notes n WHERE n.coaster_id = c.id AND n.note = v.note);
